extra_head_css:
.crop-wrapper { position: relative; display: inline-block; max-width: 100%; }
    .crop-overlay {
      position: absolute; border: 2px dashed var(--accent); background: rgba(99,102,241,0.1);
      cursor: move; top: 20%; left: 20%; width: 60%; height: 60%;
    }
    .crop-handle {
      position: absolute; width: 12px; height: 12px; background: var(--accent); border-radius: 50%;
    }
    .crop-handle.nw { top: -6px; left: -6px; cursor: nw-resize; }
    .crop-handle.ne { top: -6px; right: -6px; cursor: ne-resize; }
    .crop-handle.sw { bottom: -6px; left: -6px; cursor: sw-resize; }
    .crop-handle.se { bottom: -6px; right: -6px; cursor: se-resize; }
